#TOOLS GERAIS

MSG_PT[validar_senha_min]="❌ Por segurança, sua senha precisa ter no mínimo %s caracteres."
MSG_EN[validar_senha_min]="❌ For security, your password needs at least %s characters."
MSG_ES[validar_senha_min]="❌ Por seguridad, su contraseña necesita al menos %s caracteres."

MSG_PT[validar_senha_maiuscula]="🔠 Falta pelo menos uma letra maiúscula."
MSG_EN[validar_senha_maiuscula]="🔠 Missing at least one uppercase letter."
MSG_ES[validar_senha_maiuscula]="🔠 Falta al menos una letra mayúscula."

MSG_PT[validar_senha_minuscula]="🔡 Inclua ao menos uma letra minúscula."
MSG_EN[validar_senha_minuscula]="🔡 Include at least one lowercase letter."
MSG_ES[validar_senha_minuscula]="🔡 Incluya al menos una letra minúscula."

MSG_PT[validar_senha_numero]="🔢 Quase lá! Inclua pelo menos um número."
MSG_EN[validar_senha_numero]="🔢 Almost there! Include at least one number."
MSG_ES[validar_senha_numero]="🔢 ¡Ya casi! Incluya al menos un número."

MSG_PT[validar_senha_especial]="🔣 Inclua pelo menos um caractere especial: @ ou _."
MSG_EN[validar_senha_especial]="🔣 Include at least one special character: @ or _."
MSG_ES[validar_senha_especial]="🔣 Incluya al menos un carácter especial: @ o _."

MSG_PT[validar_senha_invalido]="⚠️ Caracteres inválidos detectados. Use somente letras, números e @ ou _."
MSG_EN[validar_senha_invalido]="⚠️ Invalid characters detected. Use only letters, numbers and @ or _."
MSG_ES[validar_senha_invalido]="⚠️ Caracteres inválidos detectados. Use solo letras, números y @ o _."

MSG_PT[validar_senha_resumo]="\e[31mSua senha não atende aos requisitos. Veja o que precisa ajustar:%s\e[0m"
MSG_EN[validar_senha_resumo]="\e[31mYour password doesn't meet the requirements. Here's what to fix:%s\e[0m"
MSG_ES[validar_senha_resumo]="\e[31mSu contraseña no cumple los requisitos. Esto es lo que debe ajustar:%s\e[0m"

validar_senha() {
    senha=$1
    tamanho_minimo=$2
    tem_erro=0
    mensagem_erro=""

    # Verifica comprimento mínimo
    if [ ${#senha} -lt $tamanho_minimo ]; then
        mensagem_erro+=$'\n'"$(t validar_senha_min "$tamanho_minimo")"
        tem_erro=1
    fi

    # Verifica letra maiúscula
    if ! [[ $senha =~ [A-Z] ]]; then
        mensagem_erro+=$'\n'"$(t validar_senha_maiuscula)"
        tem_erro=1
    fi

    # Verifica letra minúscula
    if ! [[ $senha =~ [a-z] ]]; then
        mensagem_erro+=$'\n'"$(t validar_senha_minuscula)"
        tem_erro=1
    fi

    # Verifica número
    if ! [[ $senha =~ [0-9] ]]; then
        mensagem_erro+=$'\n'"$(t validar_senha_numero)"
        tem_erro=1
    fi

    # Verifica caracteres especiais permitidos (@ ou _)
    if ! [[ $senha =~ [@_] ]]; then
        mensagem_erro+=$'\n'"$(t validar_senha_especial)"
        tem_erro=1
    fi

    # Verifica se há caracteres inválidos
    if [[ $senha =~ [^A-Za-z0-9@_] ]]; then
        mensagem_erro+=$'\n'"$(t validar_senha_invalido)"
        tem_erro=1
    fi

    # Exibe erros, se houver
    if [ $tem_erro -eq 1 ]; then
        echo -e "$(t validar_senha_resumo "$mensagem_erro")"
        return 1
    fi

    return 0
}

# Valida um nome de usuário (Portainer admin, admin do painel). Evita
# defaults previsíveis como "admin" — se um atacante já sabe o usuário, só
# falta adivinhar a senha, o que reduz a segurança pela metade.
MSG_PT[validar_usuario_tamanho]="❌ O usuário precisa ter entre 4 e 40 caracteres."
MSG_EN[validar_usuario_tamanho]="❌ The username needs to be between 4 and 40 characters."
MSG_ES[validar_usuario_tamanho]="❌ El usuario necesita tener entre 4 y 40 caracteres."

MSG_PT[validar_usuario_formato]="🔡 Use apenas letras minúsculas, números, _ ou -, começando com uma letra."
MSG_EN[validar_usuario_formato]="🔡 Use only lowercase letters, numbers, _ or -, starting with a letter."
MSG_ES[validar_usuario_formato]="🔡 Use solo letras minúsculas, números, _ o -, comenzando con una letra."

MSG_PT[validar_usuario_previsivel]="⚠️ Esse usuário é previsível demais (\"%s\") — escolha outro."
MSG_EN[validar_usuario_previsivel]="⚠️ This username is too predictable (\"%s\") — choose another one."
MSG_ES[validar_usuario_previsivel]="⚠️ Ese usuario es demasiado predecible (\"%s\") — elija otro."

MSG_PT[validar_usuario_resumo]="\e[31mUsuário inválido. Veja o que precisa ajustar:%s\e[0m"
MSG_EN[validar_usuario_resumo]="\e[31mInvalid username. Here's what to fix:%s\e[0m"
MSG_ES[validar_usuario_resumo]="\e[31mUsuario inválido. Esto es lo que debe ajustar:%s\e[0m"

validar_usuario() {
    usuario=$1
    tem_erro=0
    mensagem_erro=""

    if [ ${#usuario} -lt 4 ] || [ ${#usuario} -gt 40 ]; then
        mensagem_erro+=$'\n'"$(t validar_usuario_tamanho)"
        tem_erro=1
    fi

    if ! [[ $usuario =~ ^[a-z][a-z0-9_-]*$ ]]; then
        mensagem_erro+=$'\n'"$(t validar_usuario_formato)"
        tem_erro=1
    fi

    case "${usuario,,}" in
        admin|administrator|root|portainer|user|test|encha)
            mensagem_erro+=$'\n'"$(t validar_usuario_previsivel "$usuario")"
            tem_erro=1
            ;;
    esac

    if [ $tem_erro -eq 1 ]; then
        echo -e "$(t validar_usuario_resumo "$mensagem_erro")"
        return 1
    fi

    return 0
}

# Valida um domínio/subdomínio (FQDN) antes de usá-lo em labels do Traefik
# (Host(`$dominio`)). Mesmo regex já usado nos prompts de domínio do main.sh
# — sem essa checagem, um valor malformado vai direto para o compose e só
# quebra na hora de emitir o certificado ou rotear a requisição.
MSG_PT[validar_dominio_invalido]="\e[31m✖ Domínio inválido. Use um domínio/subdomínio válido, ex: crm.suaempresa.com\e[0m"
MSG_EN[validar_dominio_invalido]="\e[31m✖ Invalid domain. Use a valid domain/subdomain, e.g.: crm.yourcompany.com\e[0m"
MSG_ES[validar_dominio_invalido]="\e[31m✖ Dominio inválido. Use un dominio/subdominio válido, ej: crm.suempresa.com\e[0m"

validar_dominio() {
    dominio=$1

    if [[ "$dominio" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]]; then
        return 0
    fi

    echo -e "$(t validar_dominio_invalido)"
    return 1
}

# O Portainer só cria o admin via --admin-password-file com o username fixo
# "admin" (limitação da flag). Para aplicar um usuário customizado, o
# bootstrap continua como "admin" e este helper renomeia o userID 1 logo
# depois, via PUT /api/users/1 — isso não mexe no hash da senha nem invalida
# o JWT (ele carrega o userID, não o nome). Se a renomeação falhar de forma
# persistente, mantém "admin" e avisa — NUNCA aborta a instalação por causa
# disso.
#
# Uso: renomear_admin_portainer_se_necessario <rede> <usuario_alvo> <senha> <token_admin> [usuario_atual=admin]
# Efeitos: define USER_PORTAINER_FINAL (global).
# <usuario_atual> é o usuário com quem <token_admin> já autenticou — é o nome
# que fica (e que a mensagem de falha cita) se a renomeação não passar. Hoje
# o único chamador (finalizar_admin_portainer) só renomeia num banco
# recém-criado, então na prática é sempre "admin"; o parâmetro existe para a
# mensagem nunca afirmar um nome diferente do usuário que autenticou.
MSG_PT[renomear_admin_portainer_falha]="\e[33m⚠️  Não foi possível renomear o admin do Portainer para \"%s\" (HTTP %s) — mantendo \"%s\".\e[0m"
MSG_EN[renomear_admin_portainer_falha]="\e[33m⚠️  Could not rename the Portainer admin to \"%s\" (HTTP %s) — keeping \"%s\".\e[0m"
MSG_ES[renomear_admin_portainer_falha]="\e[33m⚠️  No fue posible renombrar el admin de Portainer a \"%s\" (HTTP %s) — manteniendo \"%s\".\e[0m"

MSG_PT[renomear_admin_portainer_sucesso]="\e[32m✅ Admin do Portainer renomeado para \"%s\".\e[0m"
MSG_EN[renomear_admin_portainer_sucesso]="\e[32m✅ Portainer admin renamed to \"%s\".\e[0m"
MSG_ES[renomear_admin_portainer_sucesso]="\e[32m✅ Admin de Portainer renombrado a \"%s\".\e[0m"

MSG_PT[renomear_admin_portainer_reautenticar]="\e[33m⚠️  Renomeado para \"%s\", mas falha ao reautenticar — usando token antigo.\e[0m"
MSG_EN[renomear_admin_portainer_reautenticar]="\e[33m⚠️  Renamed to \"%s\", but re-authentication failed — using the old token.\e[0m"
MSG_ES[renomear_admin_portainer_reautenticar]="\e[33m⚠️  Renombrado a \"%s\", pero falló la reautenticación — usando el token anterior.\e[0m"

renomear_admin_portainer_se_necessario() {
    local rede="$1" alvo="$2" senha="$3" token_admin="$4" usuario_atual="${5:-admin}"
    USER_PORTAINER_FINAL="$usuario_atual"

    if [ -z "$alvo" ] || [ "$alvo" = "$usuario_atual" ] || [ -z "$token_admin" ]; then
        return 0
    fi

    local ok=false http
    for _ in 1 2 3 4 5; do
        http=$(sudo docker run --rm --network "$rede" "${ENCHA_CURL_IMAGE}" \
            -s -o /dev/null -w "%{http_code}" -X PUT \
            -H "Authorization: Bearer $token_admin" \
            -H "Content-Type: application/json" \
            -d "$(jq -nc --arg u "$alvo" '{Username:$u}')" \
            http://portainer_portainer:9000/api/users/1 2>/dev/null)
        [ "$http" = "200" ] && { ok=true; break; }
        sleep 3
    done

    if [ "$ok" != true ]; then
        echo -e "$(t renomear_admin_portainer_falha "$alvo" "$http" "$usuario_atual")"
        return 0
    fi

    local novo_token
    novo_token=$(sudo docker run --rm --network "$rede" "${ENCHA_CURL_IMAGE}" \
        -s -X POST http://portainer_portainer:9000/api/auth \
        -H "Content-Type: application/json" \
        -d "$(jq -nc --arg u "$alvo" --arg p "$senha" '{username:$u,password:$p}')" 2>/dev/null | jq -r .jwt)

    if [ -n "$novo_token" ] && [ "$novo_token" != "null" ]; then
        USER_PORTAINER_FINAL="$alvo"
        echo -e "$(t renomear_admin_portainer_sucesso "$alvo")"
    else
        echo -e "$(t renomear_admin_portainer_reautenticar "$alvo")"
        USER_PORTAINER_FINAL="$alvo"
    fi
}

# Compartilhada pelas duas funções (hoje idênticas) que instalam
# Traefik+Portainer — ferramenta_traefik_e_portainer (interativa) e
# instalar_traefik_e_portainer (não-interativa). Corrige o achado INFRA-04
# da auditoria em produção:
#   1) a mensagem de sucesso era fixa ("usuário: admin") e impressa ANTES
#      de renomear_admin_portainer_se_necessario rodar — sempre mentia
#      quando o operador pedia outro usuário.
#   2) numa reinstalação sobre um 'portainer_data' preservado cujo admin já
#      tinha sido renomeado numa instalação anterior, o login era feito com
#      "admin" hardcoded — falhava sempre, e o script gravava "Criar
#      manualmente." mesmo com um admin funcional (só com outro nome).
#
# Uso: finalizar_admin_portainer <rede> <senha> <usuario_alvo> <ja_inicializado>
# Efeitos: define USER_PORTAINER_FINAL e CREDENCIAIS_APLICADAS (globais —
# mesmo contrato de renomear_admin_portainer_se_necessario, que este helper
# chama). Não guarda o JWT em nenhuma variável de efeito: quem chama só
# precisa saber o usuário final e se as credenciais foram aplicadas —
# dados_portainer grava "Token: aplicado", nunca o token de verdade
# (ver o comentário em cima do 'cat > dados_portainer' nas duas funções).
#
# Autentica tentando, em ordem, até 3 candidatos de usuário — parando no
# primeiro que autenticar:
#   a) o usuário escolhido pelo operador nesta execução (<usuario_alvo>);
#   b) o que já está salvo em /root/dados_vps/dados_portainer (sobrevive a
#      uma reinstalação sobre volume preservado; ignorado se for a string
#      de fallback "Criar manualmente.");
#   c) "admin" — o único usuário que o bootstrap do Portainer sabe criar.
# Numa instalação NOVA (<ja_inicializado> != true) só "admin" pode existir
# ainda — pula direto pra ele, sem gastar 2 chamadas HTTP fadadas a falhar.
#
# Autenticado com sucesso numa instalação NOVA, tenta renomear "admin" para o
# alvo (reaproveitando renomear_admin_portainer_se_necessario) e SÓ ENTÃO
# imprime a mensagem de sucesso — com o usuário final de verdade, sucesso ou
# não da renomeação. Numa REINSTALAÇÃO nunca renomeia: mantém o usuário que
# autenticou (ver o comentário no corpo da função).
#
# Sem nenhum candidato autenticando: CREDENCIAIS_APLICADAS fica false (quem
# chama grava "Criar manualmente.", comportamento de fallback preservado);
# numa reinstalação (só nesse caso, como já era antes deste helper) avisa
# que as credenciais não bateram.
MSG_PT[finalizar_admin_portainer_pronto]="\e[32m✅ Admin do Portainer pronto (usuário: %s)!\e[0m"
MSG_EN[finalizar_admin_portainer_pronto]="\e[32m✅ Portainer admin ready (username: %s)!\e[0m"
MSG_ES[finalizar_admin_portainer_pronto]="\e[32m✅ ¡Admin de Portainer listo (usuario: %s)!\e[0m"

MSG_PT[finalizar_admin_portainer_nao_bateram]="\e[31m❌ Já existe um admin no Portainer, mas as credenciais digitadas não bateram.\e[0m"
MSG_EN[finalizar_admin_portainer_nao_bateram]="\e[31m❌ A Portainer admin already exists, but the entered credentials did not match.\e[0m"
MSG_ES[finalizar_admin_portainer_nao_bateram]="\e[31m❌ Ya existe un admin en Portainer, pero las credenciales ingresadas no coincidieron.\e[0m"

MSG_PT[finalizar_admin_portainer_use_anteriores]="\e[31m   Use as credenciais da instalação anterior, ou remova o volume 'portainer_data' para recomeçar do zero.\e[0m"
MSG_EN[finalizar_admin_portainer_use_anteriores]="\e[31m   Use the credentials from the previous installation, or remove the 'portainer_data' volume to start from scratch.\e[0m"
MSG_ES[finalizar_admin_portainer_use_anteriores]="\e[31m   Use las credenciales de la instalación anterior, o elimine el volumen 'portainer_data' para comenzar de cero.\e[0m"

finalizar_admin_portainer() {
    local rede="$1" senha="$2" alvo="$3" ja_inicializado="$4"
    USER_PORTAINER_FINAL=""
    CREDENCIAIS_APLICADAS=false

    local candidatos=()
    if [ "$ja_inicializado" = true ]; then
        [ -n "$alvo" ] && candidatos+=("$alvo")

        local salvo=""
        if [ -f /root/dados_vps/dados_portainer ]; then
            # Chave nova (inglês) ou antiga (português) — mesmo idioma dos
            # outros leitores (stack_editavel, deploy_stack_painel_via_portainer):
            # as instalações com "Usuario:" (antes do i18n) são justamente as
            # que podem ter o admin já renomeado.
            salvo="$(grep -E '^(Username|Usuario): ' /root/dados_vps/dados_portainer 2>/dev/null | head -1 | awk -F': ' '{print $2}' | tr -d '\r')"
        fi
        if [ -n "$salvo" ] && [ "$salvo" != "Criar manualmente." ]; then
            local ja_tem_salvo=false c
            for c in "${candidatos[@]}"; do [ "$c" = "$salvo" ] && ja_tem_salvo=true; done
            [ "$ja_tem_salvo" = false ] && candidatos+=("$salvo")
        fi
    fi
    local ja_tem_admin=false c
    for c in "${candidatos[@]}"; do [ "$c" = "admin" ] && ja_tem_admin=true; done
    [ "$ja_tem_admin" = false ] && candidatos+=("admin")

    local usuario_atual="" token="" cand
    for cand in "${candidatos[@]}"; do
        token=$(sudo docker run --rm --network "$rede" "${ENCHA_CURL_IMAGE}" \
            -s -X POST http://portainer_portainer:9000/api/auth \
            -H "Content-Type: application/json" \
            -d "$(jq -nc --arg u "$cand" --arg p "$senha" '{username:$u,password:$p}')" 2>/dev/null | jq -r .jwt)
        if [ -n "$token" ] && [ "$token" != "null" ]; then
            usuario_atual="$cand"
            break
        fi
    done

    if [ -z "$usuario_atual" ]; then
        if [ "$ja_inicializado" = true ]; then
            # Reinstalação sobre admin pré-existente com credenciais
            # diferentes das digitadas agora (em nenhum dos 3 candidatos):
            # não sobrescrever dados_portainer com informação enganosa.
            echo -e "$(t finalizar_admin_portainer_nao_bateram)"
            echo -e "$(t finalizar_admin_portainer_use_anteriores)"
        fi
        return 1
    fi

    CREDENCIAIS_APLICADAS=true
    if [ "$ja_inicializado" = true ]; then
        # Reinstalação: o admin do 'portainer_data' preservado fica com o nome
        # que já tem — é o que ..._dados_preservados/..._volume_existente
        # prometem ao operador logo antes. Renomear aqui quebraria o
        # PORTAINER_USER gravado na stack do painel (a opção 2 do menu
        # reinstala só Traefik+Portainer, sem regravar o painel), e o
        # PUT /api/users/1 da renomeação só é com certeza o usuário
        # autenticado num banco recém-criado.
        USER_PORTAINER_FINAL="$usuario_atual"
    else
        renomear_admin_portainer_se_necessario "$rede" "$alvo" "$senha" "$token" "$usuario_atual"
    fi
    echo -e "$(t finalizar_admin_portainer_pronto "$USER_PORTAINER_FINAL")"
}

# Compara duas versões "X.Y.Z" (semver simples, sem pré-release/build).
# Retorna 0 (verdadeiro) só se $1 for estritamente maior que $2; formato
# fora do padrão em qualquer um dos dois é tratado como "não é maior" (1) —
# nunca aborta o script (sem 'set -e' aqui dentro).
versao_semver_maior() {
    local a="$1" b="$2"
    [[ "$a" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    [[ "$b" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    local a1 a2 a3 b1 b2 b3
    IFS=. read -r a1 a2 a3 <<< "$a"
    IFS=. read -r b1 b2 b3 <<< "$b"
    if [ "$a1" -ne "$b1" ]; then [ "$a1" -gt "$b1" ]; return $?; fi
    if [ "$a2" -ne "$b2" ]; then [ "$a2" -gt "$b2" ]; return $?; fi
    [ "$a3" -gt "$b3" ]
}

# Numa reinstalação, evita rebaixar o Portainer/agent que já está em
# execução. Chamado ANTES de qualquer 'docker stack rm portainer' (a stack
# antiga ainda precisa estar de pé para o /api/system/status responder).
#
# Lê a versão REAL hoje em execução (não a tag da imagem — que pode ser só
# "latest" numa instalação de antes deste ciclo, inútil para comparar) via
# /api/system/status do próprio Portainer ativo. Compara com
# PORTAINER_VERSION (semver simples) e decide:
#   - em uso MAIOR que a fixa -> implanta a versão em uso (nunca rebaixa);
#   - em uso MENOR OU IGUAL   -> implanta a fixa;
#   - não deu para ler (erro/vazio, ex.: instalação muito antiga sem essa
#     rota, ou rede fora do ar) OU a versão lida não é "X.Y.Z" estrito (ex.:
#     "2.46.0-rc1" — não dá para comparar com segurança) -> não arrisca:
#     reusa a imagem completa (com tag) que já está em cada serviço, tal
#     como está hoje. Implantar a fixa nesse caso poderia rebaixar.
#
# Uso: resolver_imagens_portainer <rede> <ja_inicializado>
# Efeitos: define IMAGEM_AGENT_PORTAINER e IMAGEM_SERVER_PORTAINER (globais)
# — o que os dois YAMLs (portainer-agent.yaml e portainer.yaml) devem usar.
resolver_imagens_portainer() {
    local rede="$1" ja_inicializado="$2"
    IMAGEM_AGENT_PORTAINER="portainer/agent:${PORTAINER_VERSION}"
    IMAGEM_SERVER_PORTAINER="portainer/portainer-ce:${PORTAINER_VERSION}"

    # Instalação nova: não há serviço anterior para comparar.
    [ "$ja_inicializado" = true ] || return 0

    local versao_atual
    versao_atual=$(sudo docker run --rm --network "$rede" "${ENCHA_CURL_IMAGE}" \
        -s -m 10 "http://portainer_portainer:9000/api/system/status" 2>/dev/null \
        | jq -r '.Version // empty' 2>/dev/null)

    # Versão fora do padrão X.Y.Z conta como ilegível: versao_semver_maior
    # diria "não é maior" e a fixa seria implantada — um rebaixamento se a
    # versão em uso for, por exemplo, uma 2.46.0-rc1.
    if [ -z "$versao_atual" ] || ! [[ "$versao_atual" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        local img_agent img_server
        img_agent=$(sudo docker service inspect portainer_agent --format '{{.Spec.TaskTemplate.ContainerSpec.Image}}' 2>/dev/null)
        img_server=$(sudo docker service inspect portainer_portainer --format '{{.Spec.TaskTemplate.ContainerSpec.Image}}' 2>/dev/null)
        [ -n "$img_agent" ] && IMAGEM_AGENT_PORTAINER="$img_agent"
        [ -n "$img_server" ] && IMAGEM_SERVER_PORTAINER="$img_server"
        return 0
    fi

    if versao_semver_maior "$versao_atual" "$PORTAINER_VERSION"; then
        IMAGEM_AGENT_PORTAINER="portainer/agent:${versao_atual}"
        IMAGEM_SERVER_PORTAINER="portainer/portainer-ce:${versao_atual}"
    fi
    # Menor ou igual: mantém a fixa (já preenchida no início da função).
}



MSG_PT[wait_stack_aguarde]="\e[33m⏳ Aguarde alguns instantes. Se demorar mais de 5 minutos, cancele e tente novamente.\e[0m"
MSG_EN[wait_stack_aguarde]="\e[33m⏳ Please wait a moment. If it takes more than 5 minutes, cancel and try again.\e[0m"
MSG_ES[wait_stack_aguarde]="\e[33m⏳ Espere unos instantes. Si demora más de 5 minutos, cancele y vuelva a intentar.\e[0m"

MSG_PT[wait_stack_servico]="\e[35m🛠️ Serviço:\e[0m \e[36m%s\e[0m — Réplicas detectadas: \e[33m%s\e[0m"
MSG_EN[wait_stack_servico]="\e[35m🛠️ Service:\e[0m \e[36m%s\e[0m — Replicas detected: \e[33m%s\e[0m"
MSG_ES[wait_stack_servico]="\e[35m🛠️ Servicio:\e[0m \e[36m%s\e[0m — Réplicas detectadas: \e[33m%s\e[0m"

MSG_PT[wait_stack_status]="\e[36m📊 Status do Serviço:\e[0m em execução = \e[33m%s\e[0m de \e[32m%s\e[0m"
MSG_EN[wait_stack_status]="\e[36m📊 Service status:\e[0m running = \e[33m%s\e[0m of \e[32m%s\e[0m"
MSG_ES[wait_stack_status]="\e[36m📊 Estado del servicio:\e[0m en ejecución = \e[33m%s\e[0m de \e[32m%s\e[0m"

MSG_PT[wait_stack_ativo]="\e[32m🟢 Serviço \e[32m%s\e[0m está ativo com todas as réplicas (%s)."
MSG_EN[wait_stack_ativo]="\e[32m🟢 Service \e[32m%s\e[0m is active with all replicas (%s)."
MSG_ES[wait_stack_ativo]="\e[32m🟢 Servicio \e[32m%s\e[0m está activo con todas las réplicas (%s)."

MSG_PT[wait_stack_todos_ativos]="\e[32m✅ Todos os serviços estão ativos.\e[0m"
MSG_EN[wait_stack_todos_ativos]="\e[32m✅ All services are active.\e[0m"
MSG_ES[wait_stack_todos_ativos]="\e[32m✅ Todos los servicios están activos.\e[0m"

MSG_PT[wait_stack_aguardando]="\e[36m⏳ Aguardando os serviços... (tentativa \e[33m%s/%s\e[36m)\e[0m"
MSG_EN[wait_stack_aguardando]="\e[36m⏳ Waiting for the services... (attempt \e[33m%s/%s\e[36m)\e[0m"
MSG_ES[wait_stack_aguardando]="\e[36m⏳ Esperando los servicios... (intento \e[33m%s/%s\e[36m)\e[0m"

MSG_PT[wait_stack_timeout]="\e[31m🛑 Tempo esgotado: serviços não responderam a tempo.\e[0m"
MSG_EN[wait_stack_timeout]="\e[31m🛑 Timeout: services did not respond in time.\e[0m"
MSG_ES[wait_stack_timeout]="\e[31m🛑 Tiempo agotado: los servicios no respondieron a tiempo.\e[0m"

wait_stack() {
    echo -e "$(t wait_stack_aguarde)"
    declare -A services_status=()

    # Inicializa todos os serviços como pendentes
    for service in "$@"; do
        services_status["$service"]="pendente"
    done

    local max_attempts=10
    local attempt=1

    while [ $attempt -le $max_attempts ]; do
        local all_active=true

        for service in "${!services_status[@]}"; do
            replicas=$(docker service ls --filter "name=$service" --format "{{.Replicas}}")
            echo -e "$(t wait_stack_servico "$service" "$replicas")"

            if [[ $replicas == */* ]]; then
                running=${replicas%%/*}
                total=${replicas##*/}

                echo -e "$(t wait_stack_status "$running" "$total")"

                if [ "$running" == "$total" ]; then
                    if [ "${services_status["$service"]}" != "ativo" ]; then
                        echo -e "$(t wait_stack_ativo "$service" "$replicas")"
                        services_status["$service"]="ativo"
                    fi
                else
                    all_active=false
                    services_status["$service"]="pendente"
                fi
            else
                all_active=false
                services_status["$service"]="pendente"
            fi
        done

        if $all_active; then
            echo -e "$(t wait_stack_todos_ativos)"
            return 0
        fi

        echo -e "$(t wait_stack_aguardando "$attempt" "$max_attempts")"
        attempt=$((attempt + 1))
        sleep 30
    done

    echo -e "$(t wait_stack_timeout)"
    return 1
}



wait_30_sec() {
    echo -e "\e[36m⏳ Aguardando 30 segundos...\e[0m"
    sleep 30
}


