    criar_banco_pgvector_da_stack "chatwoot${1:+_$1}"
fi

## Mensagem de Passo
MSG_PT[ferramenta_chatwoot_instalando]=$'\e[97m• INSTALANDO CHATWOOT \e[33m[3/6]\e[0m'
MSG_EN[ferramenta_chatwoot_instalando]=$'\e[97m• INSTALLING CHATWOOT \e[33m[3/6]\e[0m'
MSG_ES[ferramenta_chatwoot_instalando]=$'\e[97m• INSTALANDO CHATWOOT \e[33m[3/6]\e[0m'
echo -e "$(t ferramenta_chatwoot_instalando)"
echo ""
sleep 1

## Criando key aleatória
encryption_key=$(openssl rand -hex 16)

## Criando a stack chatwoot.yaml (Mantendo Volumes do Orion para evitar bugs)
cat > chatwoot${1:+_$1}.yaml <<EOL
version: "3.7"
services:

  chatwoot${1:+_$1}_app:
    image: chatwoot/chatwoot:latest
    command: >
      sh -c "echo 'Rails.application.config.active_storage.variant_processor = :mini_magick' > /app/config/initializers/active_storage.rb && bundle exec rails db:chatwoot_prepare && bundle exec rails s -p 3000 -b 0.0.0.0"
    entrypoint: docker/entrypoints/rails.sh    

    volumes:
      - chatwoot${1:+_$1}_storage:/app/storage
      - chatwoot${1:+_$1}_public:/app/public
      - chatwoot${1:+_$1}_mailer:/app/app/views/devise/mailer
      - chatwoot${1:+_$1}_mailers:/app/app/views/mailers

    networks:
      - $nome_rede_interna
    
    environment:
      - INSTALLATION_NAME=$nome_empresa_chatwoot
      - SECRET_KEY_BASE=$encryption_key
      - FRONTEND_URL=https://$url_chatwoot
      - FORCE_SSL=true
      - DEFAULT_LOCALE=pt_BR
      - TZ=America/Sao_Paulo
      - REDIS_URL=redis://chatwoot${1:+_$1}_redis:6379
      - POSTGRES_HOST=pgvector
      - POSTGRES_USERNAME=postgres
      - POSTGRES_PASSWORD=$senha_pgvector
      - POSTGRES_DATABASE=chatwoot${1:+_$1}
      - ACTIVE_STORAGE_SERVICE=local
      - MAILER_SENDER_EMAIL=$email_admin_chatwoot <$email_admin_chatwoot>
      - SMTP_DOMAIN=$dominio_smtp_chatwoot
      - SMTP_ADDRESS=$smtp_email_chatwoot
      - SMTP_PORT=$porta_smtp_chatwoot
      - SMTP_SSL=$sobre_ssl
      - SMTP_USERNAME=$user_smtp_chatwoot
      - SMTP_PASSWORD=$senha_email_chatwoot
      - SMTP_AUTHENTICATION=login
      - SMTP_ENABLE_STARTTLS_AUTO=true
      - SMTP_OPENSSL_VERIFY_MODE=peer
      - MAILER_INBOUND_EMAIL_DOMAIN=$email_admin_chatwoot
      - SIDEKIQ_CONCURRENCY=10
      - RACK_TIMEOUT_SERVICE_TIMEOUT=0
      - RAILS_MAX_THREADS=5
      - WEB_CONCURRENCY=2
      - ENABLE_RACK_ATTACK=false
      - NODE_ENV=production
      - RAILS_ENV=production
      - INSTALLATION_ENV=docker
      - RAILS_LOG_TO_STDOUT=true
      - USE_INBOX_AVATAR_FOR_BOT=true
      - ENABLE_ACCOUNT_SIGNUP=false

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M
      labels:
        - traefik.enable=true
        - traefik.http.routers.chatwoot${1:+_$1}_app.rule=Host(\`$url_chatwoot\`)
        - traefik.http.routers.chatwoot${1:+_$1}_app.entrypoints=websecure
        - traefik.http.routers.chatwoot${1:+_$1}_app.tls.certresolver=letsencryptresolver
        - traefik.http.routers.chatwoot${1:+_$1}_app.priority=1
        - traefik.http.routers.chatwoot${1:+_$1}_app.service=chatwoot${1:+_$1}_app
        - traefik.http.services.chatwoot${1:+_$1}_app.loadbalancer.server.port=3000
        - traefik.http.services.chatwoot${1:+_$1}_app.loadbalancer.passHostHeader=true
        - traefik.http.middlewares.sslheader.headers.customrequestheaders.X-Forwarded-Proto=https
        - traefik.http.routers.chatwoot${1:+_$1}_app.middlewares=sslheader

  chatwoot${1:+_$1}_sidekiq:
    image: chatwoot/chatwoot:latest
    command: bundle exec sidekiq -C config/sidekiq.yml
    volumes:
      - chatwoot${1:+_$1}_storage:/app/storage
      - chatwoot${1:+_$1}_public:/app/public
      - chatwoot${1:+_$1}_mailer:/app/app/views/devise/mailer
      - chatwoot${1:+_$1}_mailers:/app/app/views/mailers
    networks:
      - $nome_rede_interna
    environment:
      - INSTALLATION_NAME=$nome_empresa_chatwoot
      - SECRET_KEY_BASE=$encryption_key
      - FRONTEND_URL=https://$url_chatwoot
      - FORCE_SSL=true
      - DEFAULT_LOCALE=pt_BR
      - TZ=America/Sao_Paulo
      - REDIS_URL=redis://chatwoot${1:+_$1}_redis:6379
      - POSTGRES_HOST=pgvector
      - POSTGRES_USERNAME=postgres
      - POSTGRES_PASSWORD=$senha_pgvector
      - POSTGRES_DATABASE=chatwoot${1:+_$1}
      - ACTIVE_STORAGE_SERVICE=local
      - MAILER_SENDER_EMAIL=$email_admin_chatwoot <$email_admin_chatwoot>
      - SMTP_DOMAIN=$dominio_smtp_chatwoot
      - SMTP_ADDRESS=$smtp_email_chatwoot
      - SMTP_PORT=$porta_smtp_chatwoot
      - SMTP_SSL=$sobre_ssl
      - SMTP_USERNAME=$user_smtp_chatwoot
      - SMTP_PASSWORD=$senha_email_chatwoot
      - SMTP_AUTHENTICATION=login
      - SMTP_ENABLE_STARTTLS_AUTO=true
      - SMTP_OPENSSL_VERIFY_MODE=peer
      - MAILER_INBOUND_EMAIL_DOMAIN=$email_admin_chatwoot
      - SIDEKIQ_CONCURRENCY=10
      - RACK_TIMEOUT_SERVICE_TIMEOUT=0
      - RAILS_MAX_THREADS=5
      - WEB_CONCURRENCY=2
      - ENABLE_RACK_ATTACK=false
      - NODE_ENV=production
      - RAILS_ENV=production
      - INSTALLATION_ENV=docker
      - RAILS_LOG_TO_STDOUT=true
      - USE_INBOX_AVATAR_FOR_BOT=true
      - ENABLE_ACCOUNT_SIGNUP=false
    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M

  chatwoot${1:+_$1}_redis:
    image: redis:latest
    command: ["redis-server", "--appendonly", "yes", "--port", "6379"]
    volumes:
      - chatwoot${1:+_$1}_redis:/data
    networks:
      - $nome_rede_interna
    deploy:
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M

volumes:
  chatwoot${1:+_$1}_storage:
    external: true
    name: chatwoot${1:+_$1}_storage
  chatwoot${1:+_$1}_public:
    external: true
    name: chatwoot${1:+_$1}_public
  chatwoot${1:+_$1}_mailer:
    external: true
    name: chatwoot${1:+_$1}_mailer
  chatwoot${1:+_$1}_mailers:
    external: true
    name: chatwoot${1:+_$1}_mailers
  chatwoot${1:+_$1}_redis:
    external: true
    name: chatwoot${1:+_$1}_redis

networks:
  $nome_rede_interna:
    external: true
    name: $nome_rede_interna
EOL

if [ $? -eq 0 ]; then
    MSG_PT[ferramenta_chatwoot_stack_ok]="1/10 - [ OK ] - Criando Stack"
    MSG_EN[ferramenta_chatwoot_stack_ok]="1/10 - [ OK ] - Creating Stack"
    MSG_ES[ferramenta_chatwoot_stack_ok]="1/10 - [ OK ] - Creando Stack"
