# ==============================================================================================
# EDITOR SERVICE (BROKER)
# ==============================================================================================
cat > n8n_editor_formacao_encha.yaml <<EOL
version: "3.7"
services:
  # NOME DO SERVIÇO ENCURTADO PARA: editor
  editor:
    image: n8nio/n8n:latest
    hostname: "{{.Service.Name}}.{{.Task.Slot}}"
    command: start
    networks:
      - $nome_rede_interna
    environment:
      - N8N_ENCRYPTION_KEY=$encryption_key
      - NODE_ENV=production
      - N8N_PAYLOAD_SIZE_MAX=16
      - N8N_LOG_LEVEL=info
      - GENERIC_TIMEZONE=America/Sao_Paulo
      - N8N_ENFORCE_SETTINGS_FILE_PERMISSIONS=false
      
      # Banco de Dados
      - DB_TYPE=postgresdb
      - DB_POSTGRESDB_DATABASE=n8n_queue${1:+_$1}
      - DB_POSTGRESDB_HOST=postgres_formacao_encha
      - DB_POSTGRESDB_PORT=5432
      - DB_POSTGRESDB_USER=postgres
      - DB_POSTGRESDB_PASSWORD=$senha_postgres
      - DB_POSTGRESDB_SCHEMA=public

      # URLs e Portas
      - N8N_PORT=5678
      - N8N_HOST=$url_editorn8n
      - N8N_EDITOR_BASE_URL=https://$url_editorn8n/
      - N8N_PROTOCOL=https
      - WEBHOOK_URL=https://$url_webhookn8n/

      # Modo Queue (Redis)
      - EXECUTIONS_MODE=queue
      - QUEUE_BULL_REDIS_HOST=redis_formacao_encha
      - QUEUE_BULL_REDIS_PORT=6379
      - QUEUE_BULL_REDIS_DB=2
      
      # Manutenção
      - EXECUTIONS_DATA_PRUNE=true
      - EXECUTIONS_DATA_MAX_AGE=336

      # Bibliotecas e Permissões JS/Python
      - NODE_FUNCTION_ALLOW_BUILTIN=*
      - NODE_FUNCTION_ALLOW_EXTERNAL=moment,lodash
      - N8N_COMMUNITY_PACKAGES_ENABLED=true
      - N8N_REINSTALL_MISSING_PACKAGES=true
      # --- PERMISSÕES PYTHON LIBERADAS ---
      - N8N_PYTHON_ALLOW_STDLIB_MODULES=*
      - N8N_PYTHON_ALLOW_PIP_MODULES=*

      # --- CONFIGURAÇÃO TASK RUNNERS (Broker) ---
      - N8N_RUNNERS_ENABLED=true
      - N8N_RUNNERS_MODE=external
      - N8N_RUNNERS_AUTH_TOKEN=$runners_token
      - N8N_RUNNERS_BROKER_LISTEN_ADDRESS=0.0.0.0
      - N8N_NATIVE_PYTHON_RUNNER=true
      - N8N_SKIP_AUTH_ON_OAUTH_CALLBACK=true

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M
      labels:
        - traefik.enable=true
        - traefik.http.routers.n8n_editor_formacao_encha.rule=Host(\`$url_editorn8n\`)
        - traefik.http.routers.n8n_editor_formacao_encha.entrypoints=websecure
        - traefik.http.routers.n8n_editor_formacao_encha.tls.certresolver=letsencryptresolver
        - traefik.http.routers.n8n_editor_formacao_encha.service=n8n_editor_formacao_encha
        - traefik.http.services.n8n_editor_formacao_encha.loadbalancer.server.port=5678
        - traefik.http.services.n8n_editor_formacao_encha.loadbalancer.passHostHeader=true
      update_config:
        parallelism: 1
        delay: 30s
        order: start-first
        failure_action: rollback
networks:
  $nome_rede_interna:
    name: $nome_rede_interna
    external: true
EOL

MSG_PT[ferramenta_n8n_formacao_encha_editor_sucesso]=$'Passo \e[33m1/10\e[0m ✅ - Stack do N8N Editor criada com sucesso'
MSG_EN[ferramenta_n8n_formacao_encha_editor_sucesso]=$'Step \e[33m1/10\e[0m ✅ - N8N Editor stack created successfully'
MSG_ES[ferramenta_n8n_formacao_encha_editor_sucesso]=$'Paso \e[33m1/10\e[0m ✅ - Stack de N8N Editor creado con éxito'
MSG_PT[ferramenta_n8n_formacao_encha_editor_falha]=$'Passo \e[33m1/10\e[0m ❌ [\e[31mFALHOU\e[0m] - Falha ao criar a stack do N8N Editor'
MSG_EN[ferramenta_n8n_formacao_encha_editor_falha]=$'Step \e[33m1/10\e[0m ❌ [\e[31mFAILED\e[0m] - Failed to create the N8N Editor stack'
MSG_ES[ferramenta_n8n_formacao_encha_editor_falha]=$'Paso \e[33m1/10\e[0m ❌ [\e[31mFALLÓ\e[0m] - Error al crear el stack de N8N Editor'
if [ $? -eq 0 ]; then
    echo -e "$(t ferramenta_n8n_formacao_encha_editor_sucesso)"
else
    echo -e "$(t ferramenta_n8n_formacao_encha_editor_falha)"
fi

STACK_NAME="n8n_editor_formacao_encha"
stack_editavel 

# ATENÇÃO: Nome ajustado para o padrão Swarm (Stack_Serviço)
wait_services="n8n_editor_formacao_encha_editor"
wait_stack $wait_services


