    MSG_PT[ferramenta_nocobase_passo3]="\n📍 \e[97mPasso ${amarelo}3/4\e[0m"
    MSG_EN[ferramenta_nocobase_passo3]="\n📍 \e[97mStep ${amarelo}3/4\e[0m"
