    secret=$(openssl rand -hex 32)

    cat > calcom.yaml <<EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  calcom:
    image: calcom/cal.com:latest
    command: sh -c "yarn prisma migrate deploy && yarn start"
    networks:
      - ${nome_rede_interna}
    environment:
      - NEXT_PUBLIC_WEBAPP_URL=https://${url_calcom}
      - DATABASE_DIRECT_URL=postgresql://postgres:${senha_postgres}@postgres:5432/calcom
      - DATABASE_URL=postgresql://postgres:${senha_postgres}@postgres:5432/calcom
      - NEXTAUTH_SECRET=${secret}
      - CALENDSO_ENCRYPTION_KEY=${secret}
      # Variáveis de SMTP agora estão sendo usadas
      - EMAIL_FROM=${email_calcom}
      - EMAIL_SERVER_USER=${user_calcom}
      - EMAIL_SERVER_PASSWORD=${senha_email_calcom}
      - EMAIL_SERVER_HOST=${smtp_email_calcom}
      - EMAIL_SERVER_PORT=${porta_smtp_calcom}
    deploy:
      labels:
        - "traefik.enable=true"
        - "traefik.http.routers.calcom.rule=Host(\`${url_calcom}\`)"
        - "traefik.http.services.calcom.loadbalancer.server.port=3000"
        - "traefik.http.routers.calcom.entrypoints=websecure"
        - "traefik.http.routers.calcom.tls.certresolver=letsencryptresolver"
networks:
  ${nome_rede_interna}:
    external: true
EOL

    STACK_NAME="calcom"
    stack_editavel
    wait_stack calcom_calcom

    cd /root/dados_vps
    cat > dados_calcom <<EOL
[ CAL.COM ]

Dominio: https://${url_calcom}
Usuario: (criado no primeiro acesso)
Senha: (criada no primeiro acesso)
EOL

    cd

    msg_resumo_informacoes
    MSG_PT[ferramenta_calcom_sucesso]="✅ Cal.com instalado com sucesso!"
    MSG_EN[ferramenta_calcom_sucesso]="✅ Cal.com installed successfully!"
    MSG_ES[ferramenta_calcom_sucesso]="✅ ¡Cal.com instalado con éxito!"
    echo "$(t ferramenta_calcom_sucesso)"
    MSG_PT[ferramenta_calcom_acesse]="Acesse em: https://%s"
    MSG_EN[ferramenta_calcom_acesse]="Access it at: https://%s"
    MSG_ES[ferramenta_calcom_acesse]="Acceda en: https://%s"
    echo "$(t ferramenta_calcom_acesse "$url_calcom")"
    MSG_PT[ferramenta_calcom_crie_usuario]="Crie seu usuário no primeiro acesso."
    MSG_EN[ferramenta_calcom_crie_usuario]="Create your user on first access."
    MSG_ES[ferramenta_calcom_crie_usuario]="Cree su usuario en el primer acceso."
    echo "$(t ferramenta_calcom_crie_usuario)"
    msg_retorno_menu
}

