    MSG_PT[ferramenta_ollama_confirma]=$'\n\e[32m✅ As respostas estão corretas?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_EN[ferramenta_ollama_confirma]=$'\n\e[32m✅ Are the answers correct?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_ES[ferramenta_ollama_confirma]=$'\n\e[32m✅ ¿Las respuestas están correctas?\e[0m \e[33m(Y/N)\e[0m: '
    read -p "$(t ferramenta_ollama_confirma)" confirmacao
    if [[ "$confirmacao" =~ ^[Yy]$ ]]; then break; else msg_ollama; fi
  done

  clear
  MSG_PT[ferramenta_ollama_iniciando]="\e[97m🚀 Iniciando a instalação do Ollama & OpenWebUI...\e[0m"
  MSG_EN[ferramenta_ollama_iniciando]="\e[97m🚀 Starting Ollama & OpenWebUI installation...\e[0m"
  MSG_ES[ferramenta_ollama_iniciando]="\e[97m🚀 Iniciando la instalación de Ollama y OpenWebUI...\e[0m"
  echo -e "$(t ferramenta_ollama_iniciando)"

  WEBUI_SECRET_KEY=$(openssl rand -hex 16)
  cat > ollama.yaml << EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  ollama:
    image: ollama/ollama:latest
    volumes:
      - ollama_data:/root/.ollama
    networks:
      - $nome_rede_interna
    environment:
      - OLLAMA_HOST=0.0.0.0
    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      labels:
        - "traefik.enable=true"
        - "traefik.http.routers.ollama.rule=Host(\`$url_apiollama\`)"
        - "traefik.http.services.ollama.loadbalancer.server.port=11434"
        - "traefik.http.routers.ollama.service=ollama"
        - "traefik.http.routers.ollama.entrypoints=websecure"
        - "traefik.http.routers.ollama.tls.certresolver=letsencryptresolver"
  openwebui:
    image: ghcr.io/open-webui/open-webui:main
    volumes:
      - openwebui_data:/app/backend/data
    networks:
      - $nome_rede_interna
    environment:
      - OLLAMA_BASE_URL=https://$url_apiollama
      - WEBUI_SECRET_KEY=$WEBUI_SECRET_KEY
    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      labels:
        - "traefik.enable=true"
        - "traefik.http.routers.openwebui.rule=Host(\`$url_ollama\`)"
        - "traefik.http.services.openwebui.loadbalancer.server.port=8080"
        - "traefik.http.routers.openwebui.service=openwebui"
        - "traefik.http.routers.openwebui.entrypoints=websecure"
        - "traefik.http.routers.openwebui.tls.certresolver=letsencryptresolver"
volumes:
  ollama_data:
  openwebui_data:
networks:
  $nome_rede_interna:
    external: true
EOL

  STACK_NAME="ollama"
  stack_editavel
  wait_stack "ollama_openwebui" "ollama_ollama"

  cd /root/dados_vps
  cat > dados_ollama <<EOL
[ OLLAMA ]
WebUI: https://$url_ollama
API: https://$url_apiollama
EOL

  cd
  msg_resumo_informacoes
  echo -e "\e[32m[ OLLAMA & OPENWEBUI ]\e[0m\n"
  MSG_PT[ferramenta_ollama_final_webui]="\e[33m🌐 WebUI:\e[97m https://%s\e[0m"
  MSG_EN[ferramenta_ollama_final_webui]="\e[33m🌐 WebUI:\e[97m https://%s\e[0m"
