networks:
  $nome_rede_interna:
    external: true
EOL

  STACK_NAME="nocodb"
  stack_editavel
  wait_stack "nocodb_nocodb"

  cd /root/dados_vps
  cat > dados_nocodb <<EOL
[ NOCODB ]
