  dify${1:+_$1}_sandbox:
    image: langgenius/dify-sandbox:0.2.11

    networks:
      - $nome_rede_interna
    
    environment:
    ## API Key
      - API_KEY=$sandbox_key

    ## Configurações
      - GIN_MODE=release
      - WORKER_TIMEOUT=15
      - ENABLE_NETWORK=true
      - SANDBOX_PORT=8194

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "2"
          memory: 4096M

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
