      - PIP_MIRROR_URL=

    ## Redis
      - REDIS_HOST=redis
      - REDIS_PORT=6379

    ## Logs
      - LOG_LEVEL=DEBUG
      - LOG_FILE=/app/storage/plugin_daemon.log

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "2"
          memory: 4096M

