    echo -e "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    read -p "$(t ferramenta_phpmyadmin_confirma)" confirmacao
    if [[ "$confirmacao" =~ ^[Yy]$ ]]; then break; else msg_phpmyadmin; fi
  done

  clear
