ferramenta_openproject() {
  msg_openproject
  dados

  while true; do
    MSG_PT[ferramenta_openproject_passo1]="\n📍 Passo 1/1"
    MSG_EN[ferramenta_openproject_passo1]="\n📍 Step 1/1"
    MSG_ES[ferramenta_openproject_passo1]="\n📍 Paso 1/1"
