    MSG_PT[ferramenta_evoai_resumo_api]="🔗 \e[33mDomínio API:\e[97m %s\e[0m"
    MSG_EN[ferramenta_evoai_resumo_api]="🔗 \e[33mAPI Domain:\e[97m %s\e[0m"
