    MSG_PT[ferramenta_evoai_resumo_email]="📧 \e[33mEmail Admin:\e[97m %s\e[0m"
    MSG_EN[ferramenta_evoai_resumo_email]="📧 \e[33mAdmin Email:\e[97m %s\e[0m"
