  MSG_EN[ferramenta_passbolt_verif_mysql]="\e[97m• CHECKING/INSTALLING MYSQL \e[33m[2/4]\e[0m"
  MSG_ES[ferramenta_passbolt_verif_mysql]="\e[97m• VERIFICANDO/INSTALANDO MYSQL \e[33m[2/4]\e[0m"
