  MSG_EN[ferramenta_passbolt_instalando]="\e[97m• INSTALLING PASSBOLT \e[33m[4/5]\e[0m"
  MSG_ES[ferramenta_passbolt_instalando]="\e[97m• INSTALANDO PASSBOLT \e[33m[4/5]\e[0m"
  echo -e "$(t ferramenta_passbolt_instalando)"
  echo ""
  cat > passbolt${1:+_$1}.yaml <<EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  passbolt${1:+_$1}:
    image: passbolt/passbolt:latest ## Versão da aplicação

    volumes:
      - passbolt${1:+_$1}_data:/var/www/passbolt/webroot

    networks:
      - $nome_rede_interna ## Nome da rede interna

    environment:
      ## Configurações Gerais
      - APP_FULL_BASE_URL=https://$url_passbolt
      - PASSBOLT_REGISTRATION_PUBLIC=false ## false = Não permite registro de novos usuários

      ## Banco do MySQL
      - DATASOURCES_DEFAULT_HOST=mysql
      - DATASOURCES_DEFAULT_PORT=3306
      - DATASOURCES_DEFAULT_DATABASE=passbolt${1:+_$1}
      - DATASOURCES_DEFAULT_USERNAME=root
      - DATASOURCES_DEFAULT_PASSWORD=$senha_mysql

      ## Dados do SMTP
      - EMAIL_DEFAULT_FROM_NAME=Suporte
      - EMAIL_DEFAULT_FROM=$smtp_email_passbolt
      - EMAIL_TRANSPORT_DEFAULT_USERNAME=$smtp_user_passbolt
      - EMAIL_TRANSPORT_DEFAULT_PASSWORD=$smtp_pass_passbolt
      - EMAIL_TRANSPORT_DEFAULT_HOST=$smtp_host_passbolt
      - EMAIL_TRANSPORT_DEFAULT_PORT=$smtp_port_passbolt
      - EMAIL_TRANSPORT_DEFAULT_TLS=$smtp_ssltls_passbolt

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M
      labels:
        - traefik.enable=true
        - traefik.http.routers.passbolt${1:+_$1}.rule=Host(\`$url_passbolt\`)
        - traefik.http.services.passbolt${1:+_$1}.loadbalancer.server.port=80
        - traefik.http.routers.passbolt${1:+_$1}.service=passbolt${1:+_$1}
        - traefik.http.routers.passbolt${1:+_$1}.tls.certresolver=letsencryptresolver
        - traefik.http.routers.passbolt${1:+_$1}.entrypoints=websecure
        - traefik.http.routers.passbolt${1:+_$1}.tls=true

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

volumes:
  passbolt${1:+_$1}_data:
    external: true
    name: passbolt${1:+_$1}_data

networks:
  $nome_rede_interna: ## Nome da rede interna
    external: true
    name: $nome_rede_interna ## Nome da rede interna
EOL

  STACK_NAME="passbolt${1:+_$1}"
  stack_editavel

  MSG_PT[ferramenta_passbolt_verificando]="\e[97m• VERIFICANDO SERVIÇO \e[33m[5/5]\e[0m"
  MSG_EN[ferramenta_passbolt_verificando]="\e[97m• CHECKING SERVICE \e[33m[5/5]\e[0m"
  MSG_ES[ferramenta_passbolt_verificando]="\e[97m• VERIFICANDO SERVICIO \e[33m[5/5]\e[0m"
  echo -e "$(t ferramenta_passbolt_verificando)"
  echo ""

  pull passbolt/passbolt:latest
  wait_stack "passbolt${1:+_$1}_passbolt${1:+_$1}"

  wait_30_sec
  docker exec -u www-data $(docker ps --format "{{.Names}}" | grep "^passbolt${1:+_$1}") /usr/share/php/passbolt/bin/cake passbolt register_user -u "$email_user_passbolt" -f Administrador -l Master -r admin
  cd /root/dados_vps
  cat > dados_passbolt${1:+_$1} <<EOL
[ PassBolt ]

Link do Passbolt: https://$url_passbolt
Email Administrador: $email_user_passbolt
Senha Administrador: Via link magico no email
EOL

  cd

  msg_resumo_informacoes
  echo -e "\e[32m[ PASSBOLT ]\e[0m\n"
  MSG_PT[ferramenta_passbolt_resumo_dominio2]="🌐 \e[33mDomínio:\e[97m https://%s\e[0m"
  MSG_EN[ferramenta_passbolt_resumo_dominio2]="🌐 \e[33mDomain:\e[97m https://%s\e[0m"
  MSG_ES[ferramenta_passbolt_resumo_dominio2]="🌐 \e[33mDominio:\e[97m https://%s\e[0m"
  echo -e "$(t ferramenta_passbolt_resumo_dominio2 "$url_passbolt")"
  MSG_PT[ferramenta_passbolt_resumo_email2]="📧 \e[33mEmail Admin:\e[97m %s\e[0m"
  MSG_EN[ferramenta_passbolt_resumo_email2]="📧 \e[33mAdmin Email:\e[97m %s\e[0m"
  MSG_ES[ferramenta_passbolt_resumo_email2]="📧 \e[33mEmail Admin:\e[97m %s\e[0m"
  echo -e "$(t ferramenta_passbolt_resumo_email2 "$email_user_passbolt")"
  MSG_PT[ferramenta_passbolt_resumo_aviso]="⚠️  Um e-mail de configuração foi enviado para \e[97m%s\e[33m. Siga o link para definir sua senha."
  MSG_EN[ferramenta_passbolt_resumo_aviso]="⚠️  A setup email was sent to \e[97m%s\e[33m. Follow the link to set your password."
  MSG_ES[ferramenta_passbolt_resumo_aviso]="⚠️  Se envió un correo de configuración a \e[97m%s\e[33m. Siga el enlace para definir su contraseña."
  echo -e "\e[33m$(t ferramenta_passbolt_resumo_aviso "$email_user_passbolt")\e[0m"
  msg_retorno_menu

}

