    echo ""

    if [ "$porta_smtp_planka" -eq 465 ]; then
      smtp_secure_planka=true
      tls_reject=false
    else
      smtp_secure_planka=false
      tls_reject=true
    fi

    clear
    msg_planka
    MSG_PT[ferramenta_planka_revisar]="\e[33m🔍 Por favor, revise as informações abaixo:\e[0m\n"
