ferramenta_azuracast() {
  msg_azuracast
  dados

  while true; do
    MSG_PT[ferramenta_azuracast_passo]="\n📍 Passo 1/1"
    MSG_EN[ferramenta_azuracast_passo]="\n📍 Step 1/1"
    MSG_ES[ferramenta_azuracast_passo]="\n📍 Paso 1/1"
    echo -e "$(t ferramenta_azuracast_passo)"
    MSG_PT[ferramenta_azuracast_pergunta_dominio]="🔗 \e[33mDigite o domínio para o AzuraCast (ex: radio.encha.ai): \e[0m"
    MSG_EN[ferramenta_azuracast_pergunta_dominio]="🔗 \e[33mEnter the domain for AzuraCast (e.g. radio.encha.ai): \e[0m"
    MSG_ES[ferramenta_azuracast_pergunta_dominio]="🔗 \e[33mIngrese el dominio para el AzuraCast (ej: radio.encha.ai): \e[0m"
    echo -en "$(t ferramenta_azuracast_pergunta_dominio)" && read -r url_azuracast
    echo ""

    clear
    msg_azuracast
    MSG_PT[ferramenta_azuracast_revise]="\e[33m🔍 Por favor, revise as informações abaixo:\e[0m\n"
    MSG_EN[ferramenta_azuracast_revise]="\e[33m🔍 Please review the information below:\e[0m\n"
    MSG_ES[ferramenta_azuracast_revise]="\e[33m🔍 Por favor, revise la información abajo:\e[0m\n"
    echo -e "$(t ferramenta_azuracast_revise)"
    echo -e "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    MSG_PT[ferramenta_azuracast_dominio]="🌐 \e[33mDomínio AzuraCast:\e[97m %s\e[0m"
    MSG_EN[ferramenta_azuracast_dominio]="🌐 \e[33mAzuraCast Domain:\e[97m %s\e[0m"
    MSG_ES[ferramenta_azuracast_dominio]="🌐 \e[33mDominio AzuraCast:\e[97m %s\e[0m"
    echo -e "$(t ferramenta_azuracast_dominio "$url_azuracast")"
    echo -e "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    MSG_PT[ferramenta_azuracast_confirma]=$'\n\e[32m✅ As respostas estão corretas?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_EN[ferramenta_azuracast_confirma]=$'\n\e[32m✅ Are the answers correct?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_ES[ferramenta_azuracast_confirma]=$'\n\e[32m✅ ¿Las respuestas están correctas?\e[0m \e[33m(Y/N)\e[0m: '
    read -p "$(t ferramenta_azuracast_confirma)" confirmacao
    if [[ "$confirmacao" =~ ^[Yy]$ ]]; then break; else msg_azuracast; fi
  done

  clear
  MSG_PT[ferramenta_azuracast_iniciando]="\e[97m🚀 Iniciando a instalação do AzuraCast...\e[0m"
  MSG_EN[ferramenta_azuracast_iniciando]="\e[97m🚀 Starting AzuraCast installation...\e[0m"
  MSG_ES[ferramenta_azuracast_iniciando]="\e[97m🚀 Iniciando la instalación del AzuraCast...\e[0m"
  echo -e "$(t ferramenta_azuracast_iniciando)"
  
  azuracast_mysql_password=$(openssl rand -hex 16)

  cat > azuracast${1:+_$1}.yaml <<EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  azuracast${1:+_$1}_web:
    image: ghcr.io/azuracast/azuracast:latest

    volumes:
      - azuracast${1:+_$1}_station_data:/var/azuracast/stations
      - azuracast${1:+_$1}_backups:/var/azuracast/backups
      - azuracast${1:+_$1}_db_data:/var/lib/mysql
      - azuracast${1:+_$1}_www_uploads:/var/azuracast/storage/uploads
      - azuracast${1:+_$1}_shoutcast2_install:/var/azuracast/storage/shoutcast2
      - azuracast${1:+_$1}_stereo_tool_install:/var/azuracast/storage/stereo_tool
      - azuracast${1:+_$1}_rsas_install:/var/azuracast/storage/rsas
      - azuracast${1:+_$1}_geolite_install:/var/azuracast/storage/geoip
      - azuracast${1:+_$1}_sftpgo_data:/var/azuracast/storage/sftpgo
      - azuracast${1:+_$1}_acme:/var/azuracast/storage/acme

    networks:
      - $nome_rede_interna ## Nome da rede interna
    ports:
      - target: 2022
        published: 2022
        protocol: tcp
        mode: host
      - target: 8005
        published: 8005
        protocol: tcp
        mode: host

    environment:
      ## Identificação do Projeto
      - COMPOSE_PROJECT_NAME=azuracast

      ## Configurações de Portas
      - AZURACAST_HTTP_PORT=80
      - AZURACAST_HTTPS_PORT=443
      - AZURACAST_SFTP_PORT=2022

      ## Configurações de Permissões
      - AZURACAST_PUID=1000
      - AZURACAST_PGID=1000

      ## Configurações de Performance
      - NGINX_TIMEOUT=1800

      ## Configurações do MySQL (INTERNO)
      - ENABLE_INTERNAL_MYSQL=true
      - MYSQL_ROOT_PASSWORD=$azuracast_mysql_password ## Senha do MySQL (INTERNO)
      - MYSQL_DATABASE=azuracast
      - MYSQL_USER=azuracast
      - MYSQL_PASSWORD=$azuracast_mysql_password ## Senha do usuário do MySQL (INTERNO)
      - MYSQL_CHARACTER_SET_SERVER=utf8mb4
      - MYSQL_COLLATION_SERVER=utf8mb4_unicode_ci
    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      labels:
        - traefik.enable=1
        - traefik.http.routers.azuracast${1:+_$1}_web.rule=Host(\`$url_azuracast\`) ## Dominio para aplicação
        - traefik.http.routers.azuracast${1:+_$1}_web.entrypoints=websecure
        - traefik.http.routers.azuracast${1:+_$1}_web.priority=1
        - traefik.http.routers.azuracast${1:+_$1}_web.tls.certresolver=letsencryptresolver
        - traefik.http.routers.azuracast${1:+_$1}_web.service=azuracast${1:+_$1}_web
        - traefik.http.services.azuracast${1:+_$1}_web.loadbalancer.server.port=80
        - traefik.http.services.azuracast${1:+_$1}_web.loadbalancer.passHostHeader=true

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  azuracast${1:+_$1}_updater:
    image: ghcr.io/azuracast/updater:latest

    volumes:
      - /var/run/docker.sock:/var/run/docker.sock

    networks:
      - $nome_rede_interna ## Nome da rede interna

    deploy:
      mode: replicated
      replicas: 1
      placement:
