  MSG_EN[ferramenta_rustdesk_resumo_titulo]="\e[32m[ RUSTDESK ]\e[0m\n"
  MSG_ES[ferramenta_rustdesk_resumo_titulo]="\e[32m[ RUSTDESK ]\e[0m\n"
