  MSG_EN[ferramenta_rustdesk_resumo_key]="\e[33m🔑 Key:\e[97m %s\e[0m"
  MSG_ES[ferramenta_rustdesk_resumo_key]="\e[33m🔑 Key:\e[97m %s\e[0m"
