    read -p "$(t ferramenta_unoapi_confirma)" confirmacao
    if [[ "$confirmacao" =~ ^[Yy]$ ]]; then break; else msg_unoapi; fi
  done

  clear
  MSG_PT[ferramenta_unoapi_step1]="\e[97m• INICIANDO A INSTALAÇÃO DA UNO API \e[33m[1/3]\e[0m"
  MSG_EN[ferramenta_unoapi_step1]="\e[97m• STARTING UNO API INSTALLATION \e[33m[1/3]\e[0m"
  MSG_ES[ferramenta_unoapi_step1]="\e[97m• INICIANDO LA INSTALACIÓN DE UNO API \e[33m[1/3]\e[0m"
  echo -e "$(t ferramenta_unoapi_step1)"
  echo ""

  MSG_PT[ferramenta_unoapi_step2]="\e[97m• INSTALANDO UNO API \e[33m[2/3]\e[0m"
  MSG_EN[ferramenta_unoapi_step2]="\e[97m• INSTALLING UNO API \e[33m[2/3]\e[0m"
  MSG_ES[ferramenta_unoapi_step2]="\e[97m• INSTALANDO UNO API \e[33m[2/3]\e[0m"
  echo -e "$(t ferramenta_unoapi_step2)"
  echo ""

  cat > unoapi${1:+_$1}.yaml <<EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  unoapi${1:+_$1}:
    image: clairton/unoapi-cloud:latest
    entrypoint: yarn cloud

    volumes:
      - unoapi${1:+_$1}_data:/home/u/app

    networks:
      - $nome_rede_interna

    environment:
      ## Url Uno API
      - BASE_URL=https://$url_unoapi

      ## Token Uno Api
      - UNOAPI_AUTH_TOKEN=any

      ## Configurações da Uno API
      - IGNORE_GROUP_MESSAGES=$op_1
      - IGNORE_BROADCAST_STATUSES=$op_2
      - IGNORE_BROADCAST_MESSAGES=$op_3
      - IGNORE_STATUS_MESSAGE=$op_4
      - IGNORE_OWN_MESSAGES=$op_5
      - REJECT_CALLS=
      - REJECT_CALLS_WEBHOOK=
      - SEND_CONNECTION_STATUS=$op_6

      ## Sobre Webhook
      - WEBHOOK_URL=https://$url_chatwoot_uno/webhooks/whatsapp
      - WEBHOOK_HEADER=api_access_token
      - WEBHOOK_TOKEN=$token_chatwoot_uno

      ## Dados do Minio/S3
      - STORAGE_ENDPOINT=https://$url_s3
      - STORAGE_ACCESS_KEY_ID=$S3_ACCESS_KEY
      - STORAGE_SECRET_ACCESS_KEY=$S3_SECRET_KEY
      - STORAGE_BUCKET_NAME=unoapi${1:+_$1}
      - STORAGE_FORCE_PATH_STYLE=true

      ## Dados do RabbitMQ
      - AMQP_URL=amqp://$user_rabbit_mqs:$senha_rabbit_mqs@rabbitmq:5672/unoapi${1:+_$1}
      
      ## Dados do Redis
      - REDIS_URL=redis://redis:6379

      ## Outras configurações
      - LOG_LEVEL=debug
      - UNO_LOG_LEVEL=debug
      - UNOAPI_RETRY_REQUEST_DELAY=1_000

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M
      labels:
        - traefik.enable=true
        - traefik.http.routers.unoapi${1:+_$1}.rule=Host(\`$url_unoapi\`)
        - traefik.http.routers.unoapi${1:+_$1}.entrypoints=websecure
        - traefik.http.routers.unoapi${1:+_$1}.tls.certresolver=letsencryptresolver
        - traefik.http.services.unoapi${1:+_$1}.loadbalancer.server.port=9876
        - traefik.http.routers.unoapi${1:+_$1}.priority=1
        - traefik.http.services.unoapi${1:+_$1}.loadbalancer.passHostHeader=true
        - traefik.http.routers.unoapi${1:+_$1}.service=unoapi${1:+_$1}

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀
volumes:
  unoapi${1:+_$1}_data:
    external: true
    name: unoapi${1:+_$1}_data

networks:
  $nome_rede_interna:
    external: true
    name: $nome_rede_interna
EOL

  STACK_NAME="unoapi${1:+_$1}"
  stack_editavel

  MSG_PT[ferramenta_unoapi_step3]="\e[97m• VERIFICANDO SERVIÇO \e[33m[3/3]\e[0m"
  MSG_EN[ferramenta_unoapi_step3]="\e[97m• CHECKING SERVICE \e[33m[3/3]\e[0m"
  MSG_ES[ferramenta_unoapi_step3]="\e[97m• VERIFICANDO SERVICIO \e[33m[3/3]\e[0m"
  echo -e "$(t ferramenta_unoapi_step3)"
  echo ""

  pull clairton/unoapi-cloud:latest
  wait_stack unoapi${1:+_$1}_unoapi${1:+_$1}

  cd /root/dados_vps
  cat > dados_unoapi${1:+_$1} <<EOL
[ UNO API ]

Dominio do unoapi: https://$url_unoapi

Auth Token: any

EOL

  cd

  msg_resumo_informacoes
  echo -e "\e[32m[ UNO API ]\e[0m"
  echo ""
  MSG_PT[ferramenta_unoapi_resumo_dominio]="\e[33mDominio:\e[97m https://%s\e[0m"
  MSG_EN[ferramenta_unoapi_resumo_dominio]="\e[33mDomain:\e[97m https://%s\e[0m"
  MSG_ES[ferramenta_unoapi_resumo_dominio]="\e[33mDominio:\e[97m https://%s\e[0m"
  echo -e "$(t ferramenta_unoapi_resumo_dominio "$url_unoapi")"
