  MSG_EN[ferramenta_unoapi_resumo_ping]="\e[33mPing:\e[97m https://%s/ping\e[0m"
  MSG_ES[ferramenta_unoapi_resumo_ping]="\e[33mPing:\e[97m https://%s/ping\e[0m"
