    MSG_PT[ferramenta_moodle_confirma]=$'\n\e[32m✅ As respostas estão corretas?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_EN[ferramenta_moodle_confirma]=$'\n\e[32m✅ Are the answers correct?\e[0m \e[33m(Y/N)\e[0m: '
    MSG_ES[ferramenta_moodle_confirma]=$'\n\e[32m✅ ¿Las respuestas son correctas?\e[0m \e[33m(Y/N)\e[0m: '
    read -p "$(t ferramenta_moodle_confirma)" confirmacao
    if [[ "$confirmacao" =~ ^[Yy]$ ]]; then break; else msg_moodle; fi
  done

  clear
  MSG_PT[ferramenta_moodle_iniciando]="\e[97m🚀 Iniciando a instalação do Moodle...\e[0m"
  MSG_EN[ferramenta_moodle_iniciando]="\e[97m🚀 Starting Moodle installation...\e[0m"
  MSG_ES[ferramenta_moodle_iniciando]="\e[97m🚀 Iniciando la instalación de Moodle...\e[0m"
  echo -e "$(t ferramenta_moodle_iniciando)"

  senha_marinadb=$(openssl rand -hex 16)
  cat > moodle${1:+_$1}.yaml <<EOL
version: "3.7"
services:

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  moodle${1:+_$1}_app:
    image: bitnami/moodle:latest

    volumes:
      - moodle${1:+_$1}_data:/bitnami/moodle
      - moodle${1:+_$1}data_data:/bitnami/moodledata

    networks:
       - $nome_rede_interna ## Nome da rede interna

    environment:
      ## Dados do projeto
      - MOODLE_SITE_NAME=$project_name_moodle

      ## Dados de acesso
      - MOODLE_HOST=$url_moodle
      - MOODLE_USERNAME=$user_moodle
      - MOODLE_PASSWORD=$pass_moodle
      - MOODLE_EMAIL=$mail_moodle

      ## Dados SMTP
      - MOODLE_SMTP_USER=$usuario_smtp_moodle
      - MOODLE_SMTP_PASSWORD=$senha_smtp_moodle
      - MOODLE_SMTP_HOST=$host_smtp_moodle
      - MOODLE_SMTP_PORT_NUMBER=$porta_smtp_moodle
      - MOODLE_SMTP_PROTOCOL=$smtp_secure_smtp_moodle ## 587 = tls ou plain | 465 = ssl 

      ## Idioma
      - MOODLE_LANG=pt
      
      ## Dados MarinaDB
      - MOODLE_DATABASE_HOST=moodle${1:+_$1}_mariadb
      - MOODLE_DATABASE_PORT_NUMBER=3306
      - MOODLE_DATABASE_USER=encha_moodle
      - MOODLE_DATABASE_PASSWORD=$senha_marinadb
      - MOODLE_DATABASE_NAME=enchabase_moodle
      - ALLOW_EMPTY_PASSWORD=no

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M
      labels:
        - traefik.enable=true
        - traefik.http.routers.moodle${1:+_$1}.rule=Host(\`$url_moodle\`)
        - traefik.http.services.moodle${1:+_$1}.loadbalancer.server.port=8080
        - traefik.http.routers.moodle${1:+_$1}.service=moodle${1:+_$1}
        - traefik.http.routers.moodle${1:+_$1}.tls.certresolver=letsencryptresolver
        - traefik.http.routers.moodle${1:+_$1}.entrypoints=websecure
        - traefik.http.routers.moodle${1:+_$1}.tls=true

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

  moodle${1:+_$1}_mariadb:
    image: bitnami/mariadb:latest

    volumes:
      - moodle${1:+_$1}_mariadb_data:/bitnami/mariadb

    networks:
       - $nome_rede_interna ## Nome da rede interna

    environment:  
      ## Dados MarinaDB
      - MARIADB_USER=encha_moodle
      - MARIADB_ROOT_PASSWORD=$senha_marinadb
      - MARIADB_DATABASE=enchabase_moodle
      - MARIADB_PASSWORD=$senha_marinadb
      - MARIADB_CHARACTER_SET=utf8mb4
      - MARIADB_COLLATE=utf8mb4_unicode_ci
      - ALLOW_EMPTY_PASSWORD=no

    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      resources:
        limits:
          cpus: "1"
          memory: 1024M

# ░█▀▀░█▀█░█▀▀░█░█░█▀█░░░░█▀█░▀█▀
# ░█▀▀░█░█░█░░░█▀█░█▀█░░░░█▀█░░█░
# ░▀▀▀░▀░▀░▀▀▀░▀░▀░▀░▀░▀░░▀░▀░▀▀▀

volumes:
  moodle${1:+_$1}_data:
    external: true
    name: moodle${1:+_$1}_data
  moodle${1:+_$1}data_data:
    external: true
    name: moodle${1:+_$1}data_data
  moodle${1:+_$1}_mariadb_data:
    external: true
    name: moodle${1:+_$1}_mariadb_data

networks:
  $nome_rede_interna: ## Nome da rede interna
    name: $nome_rede_interna ## Nome da rede interna
    external: true
EOL

  STACK_NAME="moodle${1:+_$1}"
  stack_editavel

  MSG_PT[ferramenta_moodle_step_verificando]="\e[97m• VERIFICANDO SERVIÇO \e[33m[3/3]\e[0m"
  MSG_EN[ferramenta_moodle_step_verificando]="\e[97m• CHECKING SERVICE \e[33m[3/3]\e[0m"
  MSG_ES[ferramenta_moodle_step_verificando]="\e[97m• VERIFICANDO SERVICIO \e[33m[3/3]\e[0m"
  echo -e "$(t ferramenta_moodle_step_verificando)"
  echo ""

  pull bitnami/moodle:latest bitnami/mariadb:latest
  wait_stack moodle${1:+_$1}_moodle${1:+_$1}_app moodle${1:+_$1}_moodle${1:+_$1}_mariadb

  cd /root/dados_vps
  cat > dados_moodle${1:+_$1} <<EOL
[ MOODLE ]

Dominio do moodle: https://$url_moodle
Usuario: $user_moodle
Senha: $pass_moodle
EOL

  cd

  msg_resumo_informacoes
  echo -e "\e[32m[ MOODLE ]\e[0m\n"
  MSG_PT[ferramenta_moodle_resumo_dominio]="\e[33m🌐 Domínio:\e[97m https://%s\e[0m"
  MSG_EN[ferramenta_moodle_resumo_dominio]="\e[33m🌐 Domain:\e[97m https://%s\e[0m"
  MSG_ES[ferramenta_moodle_resumo_dominio]="\e[33m🌐 Dominio:\e[97m https://%s\e[0m"
  echo -e "$(t ferramenta_moodle_resumo_dominio "$url_moodle")"
  MSG_PT[ferramenta_moodle_resumo_acesse]="\e[33m⚠️  Acesse o domínio para completar a instalação e criar sua conta de administrador.\e[0m"
  MSG_EN[ferramenta_moodle_resumo_acesse]="\e[33m⚠️  Access the domain to complete the installation and create your administrator account.\e[0m"
  MSG_ES[ferramenta_moodle_resumo_acesse]="\e[33m⚠️  Acceda al dominio para completar la instalación y crear su cuenta de administrador.\e[0m"
  echo -e "$(t ferramenta_moodle_resumo_acesse)"
  msg_retorno_menu

}

ferramenta_tooljet() {
  msg_tooljet
  dados

  while true; do
    MSG_PT[ferramenta_tooljet_passo1]="\n📍 Passo 1/6"
    MSG_EN[ferramenta_tooljet_passo1]="\n📍 Step 1/6"
