    MSG_PT[ferramenta_tooljet_passo2]="\n📍 Passo 2/6"
    MSG_EN[ferramenta_tooljet_passo2]="\n📍 Step 2/6"
    MSG_ES[ferramenta_tooljet_passo2]="\n📍 Paso 2/6"
