                verificar_stack "krayincrm${opcao2:+_$opcao2}" && continue || echo ""
                if verificar_docker_e_portainer_traefik; then
                  ferramenta_krayincrm
                fi
                ;;
            80)
                verificar_stack "shlink${opcao2:+_$opcao2}" && continue || echo ""
                if verificar_docker_e_portainer_traefik; then
                  ferramenta_shlink
                fi
                ;;
            81)
                verificar "duplicati${opcao2:+_$opcao2}" && continue || echo ""
                if verificar_docker_e_portainer_traefik; then
                  ferramenta_duplicati
                fi
                ;;
            82)
              verificar "webtop${opcao2:+_$opcao2}" && continue || echo ""
              if verificar_docker_e_portainer_traefik; then
                ferramenta_webtop
              fi
              ;;
            84)
                verificar_stack "enchat" && continue || echo ""
                if verificar_docker_e_portainer_traefik; then
                    STACK_NAME="enchat"
                    ferramenta_enchat
                fi
                ;;
            96)
                instalar_protecao_ssh
                echo "Aperte ENTER para retornar ao menu de ferramentas"
                read
                ;;
            97)
                ferramenta_atualizar_painel
                echo "Aperte ENTER para retornar ao menu de ferramentas"
                read
                ;;
            98)
                if verificar_docker_e_portainer_traefik; then
                    liberar_chatwoot
                fi
                ;;
            99)
                verificar_status_servicos
                echo "Aperte ENTER para retornar ao menu de ferramentas"
                read
                sleep 2
                ;;
            100)
                echo -e "\n${verde}$(t menu_saindo)${reset}"
                sleep 1
                exit 0
                ;;
            V|v)
                # Tecla fixa "V" nos 3 idiomas de propósito (Fase 4 —
                # i18n/GLOSSARY.md): "Voltar"/"Volver" começam com V, "Back"
                # em inglês não — mas mudar a tecla mudaria o hábito de quem
                # já usa o menu hoje sem nenhum ganho real. Só o rótulo
                # (menu_opcao_voltar, na tela) e esta mensagem traduzem.
                echo "$(t menu_voltando)"
                sleep 1
                return
                ;;
            *)
                echo -e "\n${vermelho}$(t menu_opcao_invalida)${reset}"
                sleep 2
                ;;
        esac
    done
}

################################################################################
# ferramenta_atualizar_painel — Atualiza o Encha Setup Panel para a versão mais
# recente. Refresca o fonte dos scripts no host (git) e faz pull + redeploy da
# imagem nova via Docker. Equivalente, no caminho SSH, ao botão "Atualizar" do
# painel (que faz o redeploy via Portainer).
################################################################################
