MSG_PT[ferramenta_encha_panel_timeout1]="\e[41m❌ A stack encha-panel foi publicada no Portainer, mas o serviço não ficou ativo a tempo.\e[0m"
MSG_EN[ferramenta_encha_panel_timeout1]="\e[41m❌ The encha-panel stack was published to Portainer, but the service did not become active in time.\e[0m"
MSG_ES[ferramenta_encha_panel_timeout1]="\e[41m❌ La stack encha-panel fue publicada en Portainer, pero el servicio no quedó activo a tiempo.\e[0m"

MSG_PT[ferramenta_encha_panel_timeout2]="\e[41m   Verifique 'docker service ps encha-panel_panel' e 'docker service logs encha-panel_panel'.\e[0m"
MSG_EN[ferramenta_encha_panel_timeout2]="\e[41m   Check 'docker service ps encha-panel_panel' and 'docker service logs encha-panel_panel'.\e[0m"
MSG_ES[ferramenta_encha_panel_timeout2]="\e[41m   Verifique 'docker service ps encha-panel_panel' y 'docker service logs encha-panel_panel'.\e[0m"

MSG_PT[ferramenta_encha_panel_sucesso_titulo]="\e[32m║  ✅ Encha Setup Panel disponível em:                              ║\e[0m"
MSG_EN[ferramenta_encha_panel_sucesso_titulo]="\e[32m║  ✅ Encha Setup Panel available at:                               ║\e[0m"
MSG_ES[ferramenta_encha_panel_sucesso_titulo]="\e[32m║  ✅ Encha Setup Panel disponible en:                              ║\e[0m"

ferramenta_encha_panel() {
    clear
    echo -e "\e[35m╔════════════════════════════════════════════════════════════════════╗\e[0m"
    echo -e "$(t ferramenta_encha_panel_titulo)"
    echo -e "\e[35m╚════════════════════════════════════════════════════════════════════╝\e[0m"
    echo ""

    if [[ -z "$url_painel" ]]; then
        echo -e "$(t ferramenta_encha_panel_sem_url)"
        return 1
    fi

    # Knob de teste (mesma regra do ENCHA_SRC_BRANCH em main.sh): NUNCA em
    # produção — existe só pra testar uma imagem específica (ex.: uma
    # "sha-<12>" já publicada pelo CI de uma branch) numa VPS real antes de
    # publicar. Vazia por padrão -> usa a tag da versão ($ENCHA_VERSION).
    local tag_imagem_painel="${ENCHA_PANEL_IMAGE_TAG:-$ENCHA_VERSION}"

    # Garante que envsubst está disponível (vem no pacote gettext-base)
    if ! command -v envsubst >/dev/null 2>&1; then
        echo -e "$(t ferramenta_encha_panel_instalando_gettext)"
        DEBIAN_FRONTEND=noninteractive apt-get install -y gettext-base >/dev/null 2>&1
    fi

    # 1) Docker Secret idempotente (32 bytes random)
    echo -e "$(t ferramenta_encha_panel_passo1)"
    if docker secret inspect encha_panel_master_key >/dev/null 2>&1; then
        echo -e "$(t ferramenta_encha_panel_secret_existe)"
    else
        openssl rand 32 | docker secret create encha_panel_master_key - >/dev/null \
            && echo -e "$(t ferramenta_encha_panel_secret_criado)" \
            || { echo -e "$(t ferramenta_encha_panel_secret_falha)"; return 1; }
    fi

    # 2) Volume idempotente
    echo -e "$(t ferramenta_encha_panel_passo2)"
    docker volume create encha_panel_data >/dev/null \
        && echo -e "$(t ferramenta_encha_panel_volume_pronto)"

    # 3) Diretório dados_vps (bind-mount read-only do painel)
    mkdir -p /root/dados_vps
    # Auto-corrige VPS que ficaram com 700 no diretório (bug de instalações
    # 0.1.0): o container roda como uid 1001 e precisa de travessia (x) para
    # ler /app/vps-context, mesmo sem poder ler dados_portainer (600).
    chmod 755 /root/dados_vps 2>/dev/null

    # 4) Obter imagem (pull com fallback para build local)
    # Se o pull anônimo falhar (pacote privado no GHCR, rede fora, versão
    # ainda não publicada), cai no build local abaixo. Por isso o fonte
    # precisa estar na ponta do main ANTES do build, senão fixes já
    # publicados no repo não chegam à imagem (foi exatamente o que causou o
    # n8n voltar a quebrar num reinstall).
    echo -e "$(t ferramenta_encha_panel_passo3)"
    if atualizar_fonte_painel; then
        echo -e "$(t ferramenta_encha_panel_fonte_ok)"
    else
        echo -e "$(t ferramenta_encha_panel_fonte_falhou)"
    fi

    # Puxa pela tag pinada ($tag_imagem_painel — igual a $ENCHA_VERSION,
    # exceto quando o knob de teste ENCHA_PANEL_IMAGE_TAG está definido), não
    # "latest" — host-dirs.ts, no painel, procura localmente
    # "setup-panel:${APP_VERSION}" antes de puxar um fallback do Docker Hub
    # pra criar bind mounts; se só ":latest" estivesse cacheado, essa
    # checagem local nunca bateria (Docker não sabe que duas tags apontam
    # pro mesmo dígest sem baixar as duas).
    echo -e "$(t ferramenta_encha_panel_passo4 "$tag_imagem_painel")"
    if docker pull "ghcr.io/enchaaluno/setup-panel:$tag_imagem_painel" >/dev/null 2>&1; then
        echo -e "$(t ferramenta_encha_panel_imagem_ghcr)"
    elif [[ -d /root/encha-setup-panel/src ]]; then
        echo -e "$(t ferramenta_encha_panel_pull_falhou)"
        echo -e "$(t ferramenta_encha_panel_log_completo)"
        docker build -t "ghcr.io/enchaaluno/setup-panel:$tag_imagem_painel" /root/encha-setup-panel/ \
            > /var/log/encha-build.log 2>&1 &
        local build_pid=$!
        local start=$SECONDS
        while kill -0 "$build_pid" 2>/dev/null; do
            local elapsed=$((SECONDS - start))
            printf "$(t ferramenta_encha_panel_buildando)" "$elapsed"
            sleep 30
        done
        printf "\r%80s\r" " "
        wait "$build_pid"
        local build_exit=$?
        if [[ $build_exit -eq 0 ]]; then
            echo -e "$(t ferramenta_encha_panel_build_sucesso "$((SECONDS - start))")"
        else
            echo -e "$(t ferramenta_encha_panel_build_falhou "$build_exit")"
            tail -20 /var/log/encha-build.log
            return 1
        fi
    else
        echo -e "$(t ferramenta_encha_panel_sem_imagem)"
        return 1
    fi

    # 5) Render do docker-stack.yaml com envsubst — SÓ a rede. O host e as
    # credenciais (PANEL_ADMIN_*, PORTAINER_*) ficam como ${VAR} no arquivo e
    # são resolvidos pelo Env da API do Portainer (deploy_stack_painel_via_portainer),
    # não por envsubst — é isso que os torna editáveis no Portainer depois.
    echo -e "$(t ferramenta_encha_panel_passo5)"
    export ENCHA_PANEL_NETWORK="${nome_rede_interna:-enchanet}"

    local stack_template="/root/encha-setup-panel/docker-stack.yaml"
    if [[ ! -f "$stack_template" ]]; then
        # Fallback: gera template inline se o repo não estiver no host.
        # Mantenha em sincronia com encha-setup-panel/docker-stack.yaml.
        stack_template="/tmp/encha-panel.template.yaml"
        cat > "$stack_template" <<'TEMPLATE'
version: "3.7"
services:
  panel:
    image: ghcr.io/enchaaluno/setup-panel:${PANEL_IMAGE_TAG}
    networks:
      - ${ENCHA_PANEL_NETWORK}
    secrets:
      - source: encha_panel_master_key
        target: master_key
        mode: 0444
      - source: panel_admin_password
        target: panel_admin_password
        uid: "1001"
        gid: "1001"
        mode: 0400
      - source: portainer_password
        target: portainer_password
        uid: "1001"
        gid: "1001"
        mode: 0400
    volumes:
      - encha_panel_data:/app/data
      - /root/dados_vps:/app/vps-context:ro
    environment:
      - NODE_ENV=production
      - PORTAINER_URL=http://portainer_portainer:9000
      - DB_PATH=/app/data/panel.db
      - VPS_CONTEXT_DIR=/app/vps-context
      # Vazio de propósito — NÃO por o Monitor estar descontinuado (ele não
      # está). Ver o comentário completo em docker-stack.yaml do painel
      # (fonte da verdade) e monitor.ts (fetchWithTimeout): é um limite de
      # segurança, o domínio real cai no fallback fixo em código via `||`.
      - MONITOR_BASE_URL=
      - PANEL_ADMIN_USER=${PANEL_ADMIN_USER}
      - PANEL_ADMIN_PASSWORD=${PANEL_ADMIN_PASSWORD}
      - PORTAINER_USER=${PORTAINER_USER}
      - PORTAINER_PASSWORD=${PORTAINER_PASSWORD}
      - PANEL_ADMIN_PASSWORD_FILE=${PANEL_ADMIN_PASSWORD_FILE}
      - PORTAINER_PASSWORD_FILE=${PORTAINER_PASSWORD_FILE}
    read_only: true
    tmpfs:
      - /tmp
      - /app/.next/cache
    deploy:
      mode: replicated
      replicas: 1
      placement:
        constraints:
          - node.role == manager
      update_config:
        order: start-first
        failure_action: rollback
      rollback_config:
        order: start-first
      restart_policy:
        condition: on-failure
        max_attempts: 5
      resources:
        limits:
          cpus: "1"
          memory: 512M
        reservations:
          memory: 128M
      labels:
        - "traefik.enable=true"
        - "traefik.docker.network=${ENCHA_PANEL_NETWORK}"
        - "traefik.http.routers.encha-panel.rule=Host(`${ENCHA_PANEL_HOST}`)"
        - "traefik.http.routers.encha-panel.entrypoints=websecure"
        - "traefik.http.routers.encha-panel.tls.certresolver=letsencryptresolver"
        - "traefik.http.routers.encha-panel.service=encha-panel"
        - "traefik.http.services.encha-panel.loadbalancer.server.port=3000"
secrets:
  encha_panel_master_key:
    external: true
  panel_admin_password:
    external: true
    name: ${PANEL_ADMIN_PASSWORD_SECRET_NAME:-panel_admin_password_bootstrap}
  portainer_password:
    external: true
    name: ${PORTAINER_PASSWORD_SECRET_NAME:-portainer_password_bootstrap}
volumes:
  encha_panel_data:
    external: true
    name: encha_panel_data
networks:
  ${ENCHA_PANEL_NETWORK}:
    external: true
    name: ${ENCHA_PANEL_NETWORK}
TEMPLATE
    fi

    envsubst '${ENCHA_PANEL_NETWORK}' \
        < "$stack_template" > /tmp/encha-panel.yaml

    # 6) Deploy via API do Portainer (não `docker stack deploy` — ver
    # deploy_stack_painel_via_portainer para o porquê).
    echo -e "$(t ferramenta_encha_panel_passo6)"
    if ! deploy_stack_painel_via_portainer /tmp/encha-panel.yaml "$tag_imagem_painel"; then
        return 1
    fi

    # 7) Aguarda o serviço subir — o retorno de wait_stack (1 no timeout)
    # precisa ser propagado, senão a instalação declara sucesso com o
    # painel fora do ar e o operador só descobre tentando acessar depois.
    if type wait_stack &> /dev/null; then
        if ! wait_stack "encha-panel"; then
            echo -e "$(t ferramenta_encha_panel_timeout1)"
            echo -e "$(t ferramenta_encha_panel_timeout2)"
            return 1
        fi
    else
        sleep 30
    fi

    echo ""
    echo -e "\e[32m╔════════════════════════════════════════════════════════════════════╗\e[0m"
    echo -e "$(t ferramenta_encha_panel_sucesso_titulo)"
    echo -e "\e[32m║     https://$url_painel\e[0m"
    echo -e "\e[32m╚════════════════════════════════════════════════════════════════════╝\e[0m"
    echo ""
}

main() {
    # C10 (A2): "proteger-ssh" como primeiro argumento dispara
    # instalar_protecao_ssh direto e sai — sem menu interativo. É o comando
    # exato que o painel mostra (ssh-protection-warning.tsx,
    # COMANDO_PROTEGER_SSH) quando /root/dados_vps/seguranca não existe, e
    # também o que `bash /root/SetupEnchaAI proteger-ssh` roda numa VPS já
    # instalada. Qualquer outro valor (ou nenhum) cai no menu de sempre —
    # "$@" nunca chegava a ser usado aqui antes do C10.
    case "${1:-}" in
        proteger-ssh)
            instalar_protecao_ssh
            exit $?
            ;;
        *)
            processar_menu_unlimited
            ;;
    esac
}

## Executar função principal se o script for chamado diretamente
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
fi